-- APPLIED 13 October 2026 after disposable PostgreSQL 17 rehearsal. Baseline guards reject repeats; see docs/MONDAY-WEEK1-UPDATE-CHECKPOINT.md.
-- Wednesday profile-only update authorised by supplied both-night kit/preferences.
-- NO new memberships, identity changes, status/eligibility changes, results or fixture changes.
BEGIN;
SET LOCAL timezone='UTC';
SET LOCAL lock_timeout='5s';
SET LOCAL statement_timeout='30s';
CREATE TEMP TABLE requested_wednesday_profiles(data jsonb) ON COMMIT DROP;
INSERT INTO requested_wednesday_profiles VALUES ($payload$[{"id":"b4b3cb39-f59c-4ea3-b176-8e637bfb7e8b","name":"Ghazni United","colour":"#FFFFFF","status":"active","edition":"be008d39-f175-45c1-a232-2148d84b1cf9","version":1,"eligible":true,"legacy_id":"wed-ghazni-united","preferences":[{"time":"19:00","classification":"avoid"},{"time":"21:00","classification":"avoid"}],"note":"Current organiser instructions, 13 October 2026: 19:00 avoid; 21:00 avoid. Kit #FFFFFF. This supersedes earlier availability assumptions; other private context is retained below."},{"id":"99d1aedc-409b-4495-b32c-c874ec5958e0","name":"King ADL","colour":"#111111","status":"active","edition":"be008d39-f175-45c1-a232-2148d84b1cf9","version":1,"eligible":true,"legacy_id":"wed-king-adl","preferences":[{"time":"19:00","classification":"avoid"}],"note":"Current organiser instructions, 13 October 2026: 19:00 avoid. Kit #111111. This supersedes earlier availability assumptions; other private context is retained below."},{"id":"5b5d3141-f8b7-481e-9e97-9407d8f224b9","name":"Kuq E Zi","colour":"#EB5757","status":"active","edition":"be008d39-f175-45c1-a232-2148d84b1cf9","version":1,"eligible":true,"legacy_id":"wed-kuq-e-zi","preferences":[{"time":"19:00","classification":"required"},{"time":"19:40","classification":"required"},{"time":"20:20","classification":"required"}],"note":"Current organiser instructions, 13 October 2026: 19:00 required; 19:40 required; 20:20 required. Exception: against Umoja Stars, 21:00 is permitted and required by Umoja. Kit #EB5757. This supersedes earlier availability assumptions; other private context is retained below."},{"id":"92b8f805-41b1-446a-b843-6f7cc7083e90","name":"Misfits","colour":"#1E66E5","status":"active","edition":"be008d39-f175-45c1-a232-2148d84b1cf9","version":1,"eligible":true,"legacy_id":"wed-misfits","preferences":[],"note":"Current organiser instructions, 13 October 2026: any kickoff time. Kit #1E66E5. This supersedes earlier availability assumptions; other private context is retained below."},{"id":"8f0b3cd6-a819-411e-b08c-b57a3c9367fe","name":"Rinnai","colour":"#1E66E5","status":"active","edition":"be008d39-f175-45c1-a232-2148d84b1cf9","version":1,"eligible":true,"legacy_id":"wed-rinnai","preferences":[{"time":"19:40","classification":"required"},{"time":"20:20","classification":"required"},{"time":"21:00","classification":"required"}],"note":"Current organiser instructions, 13 October 2026: 19:40 required; 20:20 required; 21:00 required. Kit #1E66E5. This supersedes earlier availability assumptions; other private context is retained below."},{"id":"bafe147f-c3ac-4285-8159-f8e13a06e067","name":"Umoja Stars","colour":"#111111","status":"active","edition":"be008d39-f175-45c1-a232-2148d84b1cf9","version":1,"eligible":true,"legacy_id":"wed-umoja-stars","preferences":[{"time":"21:00","classification":"required"}],"note":"Current organiser instructions, 13 October 2026: 21:00 required. Kit #111111. This supersedes earlier availability assumptions; other private context is retained below."},{"id":"a7306808-977f-496c-8f6c-3141529ca76c","name":"Wildcats","colour":"#F2D34F","status":"active","edition":"be008d39-f175-45c1-a232-2148d84b1cf9","version":1,"eligible":true,"legacy_id":"wed-wildcats","preferences":[],"note":"Current organiser instructions, 13 October 2026: any kickoff time. Kit #F2D34F. This supersedes earlier availability assumptions; other private context is retained below."}]$payload$::jsonb);
CREATE TEMP TABLE expected_wednesday_profiles(data jsonb) ON COMMIT DROP;
INSERT INTO expected_wednesday_profiles VALUES ($payload$[{"id":"b4b3cb39-f59c-4ea3-b176-8e637bfb7e8b","name":"Ghazni United","colour":"#FFFFFF","status":"active","edition":"be008d39-f175-45c1-a232-2148d84b1cf9","version":1,"eligible":true,"legacy_id":"wed-ghazni-united","preferences":[]},{"id":"99d1aedc-409b-4495-b32c-c874ec5958e0","name":"King ADL","colour":"#27AE60","status":"active","edition":"be008d39-f175-45c1-a232-2148d84b1cf9","version":1,"eligible":true,"legacy_id":"wed-king-adl","preferences":[]},{"id":"5b5d3141-f8b7-481e-9e97-9407d8f224b9","name":"Kuq E Zi","colour":"#EB5757","status":"active","edition":"be008d39-f175-45c1-a232-2148d84b1cf9","version":1,"eligible":true,"legacy_id":"wed-kuq-e-zi","preferences":[]},{"id":"92b8f805-41b1-446a-b843-6f7cc7083e90","name":"Misfits","colour":"#2F80ED","status":"active","edition":"be008d39-f175-45c1-a232-2148d84b1cf9","version":1,"eligible":true,"legacy_id":"wed-misfits","preferences":[]},{"id":"8f0b3cd6-a819-411e-b08c-b57a3c9367fe","name":"Rinnai","colour":"#2F80ED","status":"active","edition":"be008d39-f175-45c1-a232-2148d84b1cf9","version":1,"eligible":true,"legacy_id":"wed-rinnai","preferences":[]},{"id":"bafe147f-c3ac-4285-8159-f8e13a06e067","name":"Umoja Stars","colour":"#111111","status":"active","edition":"be008d39-f175-45c1-a232-2148d84b1cf9","version":1,"eligible":true,"legacy_id":"wed-umoja-stars","preferences":[]},{"id":"a7306808-977f-496c-8f6c-3141529ca76c","name":"Wildcats","colour":"#F2C94C","status":"active","edition":"be008d39-f175-45c1-a232-2148d84b1cf9","version":1,"eligible":true,"legacy_id":"wed-wildcats","preferences":[]}]$payload$::jsonb);
DO $$ DECLARE x jsonb;t public.teams%rowtype; BEGIN
 FOR x IN SELECT value FROM expected_wednesday_profiles,jsonb_array_elements(data) LOOP
  SELECT * INTO t FROM public.teams WHERE id=(x->>'id')::uuid AND competition_season_id='be008d39-f175-45c1-a232-2148d84b1cf9' FOR UPDATE;
  IF NOT FOUND OR t.name<>x->>'name' OR t.profile_version<>(x->>'version')::bigint OR t.kit_colour IS DISTINCT FROM x->>'colour' OR t.status<>x->>'status' THEN RAISE EXCEPTION 'Wednesday profile changed: %',x->>'name'; END IF;
  IF (SELECT coalesce(jsonb_agg(jsonb_build_object('time',kickoff_time::text,'classification',classification) ORDER BY kickoff_time)::text,'[]') FROM public.team_kickoff_preferences WHERE team_id=t.id) IS DISTINCT FROM (SELECT coalesce(jsonb_agg(value ORDER BY value->>'time')::text,'[]') FROM jsonb_array_elements(x->'preferences')) THEN RAISE EXCEPTION 'Wednesday preferences changed: %',t.name; END IF;
 END LOOP;
 IF (SELECT count(*) FROM public.teams WHERE competition_season_id='be008d39-f175-45c1-a232-2148d84b1cf9')<>16 THEN RAISE EXCEPTION 'Wednesday roster count changed'; END IF;
END $$;
CREATE TEMP TABLE protected_wednesday_release ON COMMIT DROP AS
 SELECT 'fixtures' kind,to_jsonb(f) data FROM public.fixtures f
 UNION ALL SELECT 'results',to_jsonb(r) FROM public.result_versions r
 UNION ALL SELECT 'adjustments',to_jsonb(a) FROM public.standing_adjustments a
 UNION ALL SELECT 'identity',to_jsonb(t)-'kit_colour'-'updated_at'-'profile_version' FROM public.teams t
 UNION ALL SELECT 'audit',to_jsonb(a) FROM public.admin_audit_log a;
-- Restrict every write to the seven existing, locked Wednesday team IDs.
UPDATE public.teams t SET kit_colour=v->>'colour',profile_version=t.profile_version+1
 FROM requested_wednesday_profiles,jsonb_array_elements(data) v WHERE t.id=(v->>'id')::uuid AND t.competition_season_id='be008d39-f175-45c1-a232-2148d84b1cf9';
DELETE FROM public.team_kickoff_preferences p USING public.teams t WHERE t.id=p.team_id AND t.competition_season_id='be008d39-f175-45c1-a232-2148d84b1cf9'
 AND t.id IN(SELECT (v->>'id')::uuid FROM requested_wednesday_profiles,jsonb_array_elements(data) v);
INSERT INTO public.team_kickoff_preferences(team_id,kickoff_time,classification)
 SELECT t.id,(r->>'time')::time,r->>'classification' FROM requested_wednesday_profiles,jsonb_array_elements(data) v,jsonb_array_elements(v->'preferences') r,public.teams t
 WHERE t.id=(v->>'id')::uuid AND t.competition_season_id='be008d39-f175-45c1-a232-2148d84b1cf9';
INSERT INTO public.team_fixture_notes(team_id,notes)
 SELECT t.id,v->>'note' FROM requested_wednesday_profiles,jsonb_array_elements(data) v JOIN public.teams t ON t.id=(v->>'id')::uuid AND t.competition_season_id='be008d39-f175-45c1-a232-2148d84b1cf9'
 ON CONFLICT(team_id) DO UPDATE SET notes=excluded.notes||E'\n\nPrevious private context (availability superseded above):\n'||public.team_fixture_notes.notes;
DO $$ BEGIN
 IF EXISTS(SELECT data FROM protected_wednesday_release WHERE kind='fixtures' EXCEPT SELECT to_jsonb(f) FROM public.fixtures f) OR EXISTS(SELECT data FROM protected_wednesday_release WHERE kind='results' EXCEPT SELECT to_jsonb(r) FROM public.result_versions r) OR EXISTS(SELECT data FROM protected_wednesday_release WHERE kind='adjustments' EXCEPT SELECT to_jsonb(a) FROM public.standing_adjustments a) OR EXISTS(SELECT data FROM protected_wednesday_release WHERE kind='identity' EXCEPT SELECT to_jsonb(t)-'kit_colour'-'updated_at'-'profile_version' FROM public.teams t) OR EXISTS(SELECT data FROM protected_wednesday_release WHERE kind='audit' EXCEPT SELECT to_jsonb(a) FROM public.admin_audit_log a) THEN RAISE EXCEPTION 'Protected roster, fixture, result or history changed'; END IF;
END $$;
COMMIT;
